const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a Region of Interest (ROI) covering the Jakarta Bay land reclamation projects.
  const geometry = ee.Geometry.Polygon([[
    [106.75, -6.09],
    [106.92, -6.09],
    [106.92, -6.01],
    [106.75, -6.01],
    [106.75, -6.09]
  ]]);

  // 2. Data Acquisition & Check
  // Use ESA WorldCover 2021 for land cover classification at 10m resolution.
  const esa_wc_2021 = ee.Image('ESA/WorldCover/v200/2021').select('Map');

  if (!esa_wc_2021) {
    console.log("ESA WorldCover 2021 image could not be loaded.");
    console.log("D");
    return;
  }

  // 3. Processing
  // Isolate the 'Built-up' land class (value 50). Create a binary mask.
  const builtUpMask = esa_wc_2021.eq(50);

  // Use ee.Image.pixelArea() to get the area of each pixel in square meters.
  const pixelAreaImage = ee.Image.pixelArea();

  // Multiply the built-up mask by the pixel area to get the area of built-up land per pixel.
  const builtUpAreaImage = builtUpMask.multiply(pixelAreaImage);

  // Check the number of built-up pixels to avoid C2 error.
  const pixelCountStat = builtUpMask.reduceRegion({
    reducer: ee.Reducer.sum(), // Counting pixels in a binary mask is equivalent to summing them
    geometry: geometry,
    scale: 30, // Use a coarser scale for counting to ensure efficiency
    maxPixels: 1e9
  });

  const validPixels = ee.Number(pixelCountStat.get('Map')).getInfo();

  if (validPixels === null || validPixels === 0) {
      console.log("No valid 'Built-up' pixels found in the ROI for 2021.");
      console.log("C2");
      return;
  }
  console.log(`Valid 'Built-up' pixel count: ${validPixels}`);

  // 4. Calculation
  // Sum the areas of all built-up pixels within the ROI.
  const areaStat = builtUpAreaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 10, // Use native 10m scale for accurate area calculation
    maxPixels: 1e10
  });

  const areaSqMeters = ee.Number(areaStat.get('Map'));

  // Convert area from square meters to hectares (1 hectare = 10,000 sq meters).
  const areaHectares = areaSqMeters.divide(10000).getInfo();

  if (areaHectares === null || isNaN(areaHectares)) {
    console.log("Calculation of area resulted in a null or invalid value.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  const thresholdHectares = 800;
  console.log(`Total artificial land area (2021): ${areaHectares.toFixed(2)} hectares.`);
  console.log(`Comparison threshold: ${thresholdHectares} hectares.`);

  if (areaHectares > thresholdHectares) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
